--------------------------------------------------------------------------------
-- 02_tables.sql
--
-- Tables, constraints and indexes for the hierarchy-driven approval engine.
-- 19c-compatible DDL only: no 23ai-only syntax (IF NOT EXISTS, SQL domains,
-- boolean columns) so the same script installs on ATP 19c and 23ai.
--
-- Conventions
--   * Surrogate keys are identity columns (GENERATED BY DEFAULT ON NULL) so the
--     seed script can supply stable IDs; 09_seed.sql resets each identity with
--     START WITH LIMIT VALUE afterwards.
--   * Every code column is constrained to an explicit value list. The engine
--     never invents a status the database would accept silently.
--   * APPROVAL_AUDIT deliberately has NO foreign keys - see the note above it.
--------------------------------------------------------------------------------
set define off

--==============================================================================
-- Reference data
--==============================================================================

create table departments (
  dept_id        number(6)     generated by default on null as identity
, dept_code      varchar2(20)  not null
, dept_name      varchar2(100) not null
, parent_dept_id number(6)
, active_flag    char(1)       default 'Y' not null
, constraint departments_pk        primary key (dept_id)
, constraint departments_uk        unique (dept_code)
, constraint departments_parent_fk foreign key (parent_dept_id) references departments (dept_id)
, constraint departments_active_ck check (active_flag in ('Y','N'))
);

create index departments_parent_ix on departments (parent_dept_id);

comment on table departments is 'Organisational units. Referenced by rules and requests for routing scope.';


create table cost_centers (
  cost_center varchar2(20)  not null
, cc_name     varchar2(100) not null
, dept_id     number(6)
, active_flag char(1)       default 'Y' not null
, constraint cost_centers_pk        primary key (cost_center)
, constraint cost_centers_dept_fk   foreign key (dept_id) references departments (dept_id)
, constraint cost_centers_active_ck check (active_flag in ('Y','N'))
);

create index cost_centers_dept_ix on cost_centers (dept_id);


create table approval_doc_types (
  doc_type      varchar2(30)  not null
, doc_type_name varchar2(100) not null
, source_table  varchar2(128)                 -- the business table this fronts
, url_target    varchar2(400)                 -- APEX page URL template for drill-down
, active_flag   char(1)       default 'Y' not null
, constraint approval_doc_types_pk        primary key (doc_type)
, constraint approval_doc_types_active_ck check (active_flag in ('Y','N'))
);

comment on table approval_doc_types is 'Approvable business objects. Adding a new one is data, not code.';


create table approval_roles (
  role_code   varchar2(30)  not null
, role_name   varchar2(100) not null
, description varchar2(400)
, constraint approval_roles_pk primary key (role_code)
);

comment on table approval_roles is 'Named approval capacities (CFO, FINANCE_CONTROLLER, ...) used by rule steps and orphan fallback.';


create table approval_holidays (
  holiday_date date          not null
, description  varchar2(100)
, constraint approval_holidays_pk primary key (holiday_date)
);

comment on table approval_holidays is 'Non-working days excluded from SLA due-date arithmetic.';


--==============================================================================
-- Organisation
--==============================================================================

create table employees (
  employee_id    number(9)      generated by default on null as identity
, employee_no    varchar2(30)   not null
, full_name      varchar2(120)  not null
, email          varchar2(240)  not null
, apex_username  varchar2(100)  not null
, manager_id     number(9)
, job_level      number(2)      not null
, job_title      varchar2(80)
, dept_id        number(6)
, cost_center    varchar2(20)
, approval_limit number(14,2)   default 0 not null
, active_flag    char(1)        default 'Y' not null
, created_by     varchar2(100)  default on null sys_context('userenv','session_user') not null
, created_on     timestamp      default on null systimestamp not null
, updated_by     varchar2(100)
, updated_on     timestamp
, constraint employees_pk           primary key (employee_id)
, constraint employees_no_uk        unique (employee_no)
, constraint employees_username_uk  unique (apex_username)
, constraint employees_mgr_fk       foreign key (manager_id)  references employees (employee_id)
, constraint employees_dept_fk      foreign key (dept_id)     references departments (dept_id)
, constraint employees_cc_fk        foreign key (cost_center) references cost_centers (cost_center)
, constraint employees_level_ck     check (job_level between 1 and 10)
, constraint employees_limit_ck     check (approval_limit >= 0)
, constraint employees_active_ck    check (active_flag in ('Y','N'))
, constraint employees_username_ck  check (apex_username = upper(apex_username))
, constraint employees_notself_ck   check (manager_id is null or manager_id <> employee_id)
);

-- The hierarchy walk drives off MANAGER_ID; the inbox view drives off username.
create index employees_mgr_ix  on employees (manager_id);
create index employees_dept_ix on employees (dept_id, active_flag);
create index employees_cc_ix   on employees (cost_center);

comment on column employees.job_level     is '1 = individual contributor .. 10 = CEO. Rules express "climb at least to level N".';
comment on column employees.approval_limit is 'Single-document authority in the request currency. 0 = may not approve.';
comment on column employees.apex_username  is 'Matches APP_USER regardless of auth scheme (APEX Accounts / SSO / OCI IAM).';


create table employee_roles (
  employee_id number(9)    not null
, role_code   varchar2(30) not null
, dept_id     number(6)                     -- NULL = the role is held globally
, active_flag char(1)      default 'Y' not null
, constraint employee_roles_pk        primary key (employee_id, role_code)
, constraint employee_roles_emp_fk    foreign key (employee_id) references employees (employee_id)
, constraint employee_roles_role_fk   foreign key (role_code)   references approval_roles (role_code)
, constraint employee_roles_dept_fk   foreign key (dept_id)     references departments (dept_id)
, constraint employee_roles_active_ck check (active_flag in ('Y','N'))
);

create index employee_roles_role_ix on employee_roles (role_code, dept_id, active_flag);


--==============================================================================
-- Rule matrix
--==============================================================================

create table approval_rules (
  rule_id              number(9)      generated by default on null as identity
, rule_code            varchar2(40)   not null
, rule_name            varchar2(200)  not null
, doc_type             varchar2(30)   not null
, dept_id              number(6)                     -- NULL = any department
, cost_center          varchar2(20)                  -- NULL = any cost centre
, min_amount           number(14,2)   default 0 not null    -- inclusive
, max_amount           number(14,2)                         -- exclusive; NULL = unbounded
, currency_code        char(3)        default 'USD' not null
, priority             number(4)      default 100 not null  -- lower wins
, limit_mode           varchar2(12)   default 'INDIVIDUAL' not null
, start_at_level       number(2)      default 1 not null    -- ignore managers below this
, min_approver_level   number(2)      default 2 not null    -- climb at least this high
, top_job_level        number(2)      default 10 not null   -- never climb above this
, max_levels           number(2)      default 6 not null    -- hard cap on chain length
, require_coverage     char(1)        default 'Y' not null  -- fail if amount not covered
, allow_self_approval  char(1)        default 'N' not null
, collapse_duplicates  char(1)        default 'Y' not null
, skip_inactive        char(1)        default 'Y' not null
, apply_delegations    char(1)        default 'Y' not null
, fallback_role_code   varchar2(30)                  -- used when the walk yields nobody
, sla_hours            number(4)      default 24 not null
, reminder_hours       number(4)      default 8
, escalate_after_hours number(4)      default 8
, max_escalations      number(2)      default 2 not null
, valid_from           date           default on null trunc(sysdate) not null
, valid_to             date
, active_flag          char(1)        default 'Y' not null
, created_by           varchar2(100)  default on null sys_context('userenv','session_user') not null
, created_on           timestamp      default on null systimestamp not null
, updated_by           varchar2(100)
, updated_on           timestamp
, constraint approval_rules_pk          primary key (rule_id)
, constraint approval_rules_code_uk     unique (rule_code)
, constraint approval_rules_doc_fk      foreign key (doc_type)           references approval_doc_types (doc_type)
, constraint approval_rules_dept_fk     foreign key (dept_id)            references departments (dept_id)
, constraint approval_rules_cc_fk       foreign key (cost_center)        references cost_centers (cost_center)
, constraint approval_rules_fbrole_fk   foreign key (fallback_role_code) references approval_roles (role_code)
, constraint approval_rules_amt_ck      check (max_amount is null or max_amount > min_amount)
, constraint approval_rules_minamt_ck   check (min_amount >= 0)
, constraint approval_rules_mode_ck     check (limit_mode in ('INDIVIDUAL','CUMULATIVE','NONE'))
, constraint approval_rules_level_ck    check (min_approver_level between 1 and 10
                                           and top_job_level between 1 and 10
                                           and start_at_level between 1 and 10
                                           and top_job_level >= min_approver_level)
, constraint approval_rules_maxlvl_ck   check (max_levels between 1 and 20)
, constraint approval_rules_dates_ck    check (valid_to is null or valid_to >= valid_from)
, constraint approval_rules_sla_ck      check (sla_hours > 0)
, constraint approval_rules_flags_ck    check (require_coverage    in ('Y','N')
                                           and allow_self_approval in ('Y','N')
                                           and collapse_duplicates in ('Y','N')
                                           and skip_inactive       in ('Y','N')
                                           and apply_delegations   in ('Y','N')
                                           and active_flag         in ('Y','N'))
);

-- Rule lookup is the hottest query in the engine: one row per submission.
create index approval_rules_match_ix on approval_rules (doc_type, active_flag, min_amount, max_amount);
create index approval_rules_dept_ix  on approval_rules (dept_id);
create index approval_rules_cc_ix    on approval_rules (cost_center);

comment on table  approval_rules             is 'Effective-dated routing matrix. Changing routing = changing rows here, never code.';
comment on column approval_rules.limit_mode  is 'INDIVIDUAL: stop when one approver''s own limit covers the amount. CUMULATIVE: stop when the running sum of limits covers it. NONE: level-driven only.';
comment on column approval_rules.start_at_level is 'Hierarchy candidates below this job level are not gates - the walk passes straight through them. Use it to keep team leads out of six-figure chains.';
comment on column approval_rules.priority    is 'Tie-break across overlapping rules; lower number wins, then more specific dept/cost centre.';
comment on column approval_rules.max_amount  is 'Exclusive upper bound. NULL means unbounded, which is how the top band is expressed.';


create table approval_rule_steps (
  rule_step_id  number(9)     generated by default on null as identity
, rule_id       number(9)     not null
, step_no       number(3)     not null
, position_code varchar2(10)  default 'AFTER' not null  -- BEFORE | AFTER the hierarchy chain
, approver_type varchar2(10)  not null                  -- ROLE | EMPLOYEE | LEVEL
, role_code     varchar2(30)
, employee_id   number(9)
, job_level     number(2)
, group_no      number(3)     default 1 not null        -- shared group => parallel
, step_mode     varchar2(10)  default 'SEQ' not null    -- SEQ | ALL | ANY
, mandatory_yn  char(1)       default 'Y' not null
, sla_hours     number(4)
, active_flag   char(1)       default 'Y' not null
, constraint approval_rule_steps_pk       primary key (rule_step_id)
, constraint approval_rule_steps_uk       unique (rule_id, position_code, step_no)
, constraint approval_rule_steps_rule_fk  foreign key (rule_id)     references approval_rules (rule_id)
, constraint approval_rule_steps_role_fk  foreign key (role_code)   references approval_roles (role_code)
, constraint approval_rule_steps_emp_fk   foreign key (employee_id) references employees (employee_id)
, constraint approval_rule_steps_pos_ck   check (position_code in ('BEFORE','AFTER'))
, constraint approval_rule_steps_mode_ck  check (step_mode in ('SEQ','ALL','ANY'))
, constraint approval_rule_steps_type_ck  check (
      (approver_type = 'ROLE'     and role_code   is not null and employee_id is null and job_level is null)
   or (approver_type = 'EMPLOYEE' and employee_id is not null and role_code   is null and job_level is null)
   or (approver_type = 'LEVEL'    and job_level   is not null and role_code   is null and employee_id is null))
, constraint approval_rule_steps_flag_ck  check (mandatory_yn in ('Y','N') and active_flag in ('Y','N'))
);

create index approval_rule_steps_rule_ix on approval_rule_steps (rule_id, active_flag);

comment on table approval_rule_steps is 'Mandatory approvers bolted onto the hierarchy chain (e.g. "Finance Controller always signs"). Rows sharing GROUP_NO run in parallel under STEP_MODE ALL or ANY.';


--==============================================================================
-- Delegation
--==============================================================================

create table approval_delegations (
  delegation_id number(12)     generated by default on null as identity
, delegator_id  number(9)      not null
, delegate_id   number(9)      not null
, doc_type      varchar2(30)                  -- NULL = all document types
, valid_from    date           not null
, valid_to      date           not null
, max_amount    number(14,2)                  -- NULL = delegator's full authority
, reason        varchar2(400)
, active_flag   char(1)        default 'Y' not null
, created_by    varchar2(100)  default on null sys_context('userenv','session_user') not null
, created_on    timestamp      default on null systimestamp not null
, constraint approval_delegations_pk        primary key (delegation_id)
, constraint approval_delegations_from_fk   foreign key (delegator_id) references employees (employee_id)
, constraint approval_delegations_to_fk     foreign key (delegate_id)  references employees (employee_id)
, constraint approval_delegations_doc_fk    foreign key (doc_type)     references approval_doc_types (doc_type)
, constraint approval_delegations_self_ck   check (delegator_id <> delegate_id)
, constraint approval_delegations_dates_ck  check (valid_to >= valid_from)
, constraint approval_delegations_amt_ck    check (max_amount is null or max_amount >= 0)
, constraint approval_delegations_active_ck check (active_flag in ('Y','N'))
);

create index approval_delegations_lookup_ix on approval_delegations (delegator_id, active_flag, valid_from, valid_to);
create index approval_delegations_to_ix     on approval_delegations (delegate_id, active_flag);

comment on table  approval_delegations            is 'Out-of-office proxies. Overlaps are legal; the engine takes the most specific then most recent.';
comment on column approval_delegations.max_amount is 'Caps what the proxy may act on. Above the cap the engine keeps the original approver.';


--==============================================================================
-- Runtime: requests, steps
--==============================================================================

create table approval_requests (
  request_id     number(12)     generated by default on null as identity
, request_ref    varchar2(40)   not null
, doc_type       varchar2(30)   not null
, doc_id         number(12)                    -- PK of the underlying business row
, doc_ref        varchar2(60)                  -- its human reference
, requester_id   number(9)      not null
, title          varchar2(200)  not null
, description    clob
, amount         number(14,2)   default 0 not null
, currency_code  char(3)        default 'USD' not null
, dept_id        number(6)
, cost_center    varchar2(20)
, priority_code  varchar2(10)   default 'NORMAL' not null
, status         varchar2(20)   default 'DRAFT' not null
, rule_id        number(9)                     -- rule applied at submission
, current_group  number(3)
, submitted_on   timestamp
, completed_on   timestamp
, recall_count   number(3)      default 0 not null
, row_version    number(9)      default 1 not null
, created_by     varchar2(100)  default on null sys_context('userenv','session_user') not null
, created_on     timestamp      default on null systimestamp not null
, updated_by     varchar2(100)
, updated_on     timestamp
, constraint approval_requests_pk        primary key (request_id)
, constraint approval_requests_ref_uk    unique (request_ref)
, constraint approval_requests_doc_fk    foreign key (doc_type)     references approval_doc_types (doc_type)
, constraint approval_requests_req_fk    foreign key (requester_id) references employees (employee_id)
, constraint approval_requests_dept_fk   foreign key (dept_id)      references departments (dept_id)
, constraint approval_requests_cc_fk     foreign key (cost_center)  references cost_centers (cost_center)
, constraint approval_requests_rule_fk   foreign key (rule_id)      references approval_rules (rule_id)
, constraint approval_requests_amt_ck    check (amount >= 0)
, constraint approval_requests_prio_ck   check (priority_code in ('LOW','NORMAL','HIGH','URGENT'))
, constraint approval_requests_status_ck check (status in ('DRAFT','PENDING','INFO_REQUESTED','APPROVED','REJECTED','RECALLED','WITHDRAWN'))
-- A terminal request must carry a completion timestamp, and a live one must not.
, constraint approval_requests_compl_ck  check (
      (status in ('APPROVED','REJECTED','WITHDRAWN') and completed_on is not null)
   or (status in ('DRAFT','PENDING','INFO_REQUESTED','RECALLED') and completed_on is null))
);

create index approval_requests_status_ix on approval_requests (status, doc_type);
create index approval_requests_req_ix    on approval_requests (requester_id, status);
create index approval_requests_doc_ix    on approval_requests (doc_type, doc_id);

comment on column approval_requests.status        is 'DRAFT -> PENDING -> APPROVED/REJECTED. RECALLED returns to the requester for edit; WITHDRAWN is terminal.';
comment on column approval_requests.current_group is 'Group number of the step(s) currently ACTIVE. NULL when not in flight.';
comment on column approval_requests.row_version   is 'Bumped by the engine on every state change; APEX pages use it for lost-update detection.';


create table approval_steps (
  step_id              number(12)     generated by default on null as identity
, request_id           number(12)     not null
, step_seq             number(3)      not null
, group_no             number(3)      not null
, step_mode            varchar2(10)   default 'SEQ' not null
, source_code          varchar2(12)   not null
, original_approver_id number(9)      not null
, acting_approver_id   number(9)      not null
, delegation_id        number(12)
, sla_hours            number(4)
, status               varchar2(20)   default 'PENDING' not null
, activated_on         timestamp
, sla_due_on           timestamp
, action_on            timestamp
, action_by_username   varchar2(100)
, comments             varchar2(4000)
, escalation_count     number(2)      default 0 not null
, reminder_sent_on     timestamp
, constraint approval_steps_pk         primary key (step_id)
, constraint approval_steps_seq_uk     unique (request_id, step_seq)
, constraint approval_steps_req_fk     foreign key (request_id)           references approval_requests (request_id)
, constraint approval_steps_orig_fk    foreign key (original_approver_id) references employees (employee_id)
, constraint approval_steps_act_fk     foreign key (acting_approver_id)   references employees (employee_id)
, constraint approval_steps_deleg_fk   foreign key (delegation_id)        references approval_delegations (delegation_id)
, constraint approval_steps_mode_ck    check (step_mode in ('SEQ','ALL','ANY'))
, constraint approval_steps_source_ck  check (source_code in ('HIERARCHY','RULE','FALLBACK','ESCALATION','REASSIGN'))
, constraint approval_steps_status_ck  check (status in ('PENDING','ACTIVE','APPROVED','REJECTED','SKIPPED','INFO_REQUESTED','CANCELLED','REASSIGNED'))
, constraint approval_steps_acted_ck   check (
      (status in ('APPROVED','REJECTED') and action_on is not null and action_by_username is not null)
   or (status not in ('APPROVED','REJECTED')))
, constraint approval_steps_esc_ck     check (escalation_count >= 0)
);

-- Drives the inbox: "everything ACTIVE assigned to me".
create index approval_steps_inbox_ix on approval_steps (acting_approver_id, status, sla_due_on);
-- Drives group completion checks and the timeline region.
create index approval_steps_group_ix on approval_steps (request_id, group_no, status);
-- Drives the SLA sweeper.
create index approval_steps_sla_ix   on approval_steps (status, sla_due_on);

comment on column approval_steps.original_approver_id is 'The position holder. Authority (limit/level) is always evaluated against this employee.';
comment on column approval_steps.acting_approver_id   is 'Who may actually click Approve: the delegate, the reassignee, or the original.';
comment on column approval_steps.step_mode            is 'SEQ: alone in its group. ALL: every step in the group must approve. ANY: the first approval closes the group.';


--==============================================================================
-- Audit
--
-- NO FOREIGN KEYS, DELIBERATELY. The logger runs in an autonomous transaction so
-- that a failed action is still recorded. An autonomous transaction cannot see
-- the parent transaction's uncommitted rows, so an FK to APPROVAL_REQUESTS would
-- raise ORA-02291 the first time we log the creation of a brand-new request.
-- The denormalised REQUEST_REF/DOC_TYPE keep the log readable on its own.
--==============================================================================

create table approval_audit (
  audit_id         number(12)     generated by default on null as identity
, request_id       number(12)
, step_id          number(12)
, request_ref      varchar2(40)
, doc_type         varchar2(30)
, action_code      varchar2(30)   not null
, outcome          varchar2(10)   default 'SUCCESS' not null
, from_status      varchar2(20)
, to_status        varchar2(20)
, actor_username   varchar2(100)
, actor_employee_id number(9)
, on_behalf_of_id  number(9)
, comments         varchar2(4000)
, error_code       number(6)
, error_msg        varchar2(4000)
, client_ip        varchar2(45)
, apex_session_id  number(20)
, payload          clob
, action_ts        timestamp      default on null systimestamp not null
, constraint approval_audit_pk         primary key (audit_id)
, constraint approval_audit_outcome_ck check (outcome in ('SUCCESS','WARN','ERROR'))
, constraint approval_audit_payload_ck check (payload is null or payload is json)
);

create index approval_audit_req_ix   on approval_audit (request_id, action_ts);
create index approval_audit_actor_ix on approval_audit (actor_username, action_ts);
create index approval_audit_ts_ix    on approval_audit (action_ts);

comment on table  approval_audit         is 'Append-only action log. UPDATE and DELETE are blocked by trigger; see docs/04-security.md for the blockchain-table variant.';
comment on column approval_audit.outcome is 'ERROR rows record attempts that were rejected - a denied approval is as interesting as a granted one.';


--==============================================================================
-- Notification outbox
--
-- The engine never calls APEX_MAIL inline: mail needs an APEX session, and a
-- send that fails must not roll back an approval. It queues here and an APEX
-- Automation drains the queue. See docs/02-apex-build.md, Automation 3.
--==============================================================================

create table approval_notifications (
  notification_id    number(12)     generated by default on null as identity
, request_id         number(12)     not null
, step_id            number(12)
, notify_type        varchar2(20)   not null
, recipient_email    varchar2(240)  not null
, recipient_username varchar2(100)
, template_static_id varchar2(100)  not null
, placeholders       clob
, status             varchar2(10)   default 'QUEUED' not null
, attempts           number(3)      default 0 not null
, last_error         varchar2(4000)
, queued_on          timestamp      default on null systimestamp not null
, sent_on            timestamp
, constraint approval_notifications_pk         primary key (notification_id)
, constraint approval_notifications_type_ck    check (notify_type in ('ASSIGNED','REMINDER','ESCALATED','APPROVED','REJECTED','INFO_REQUESTED','INFO_PROVIDED','RECALLED','WITHDRAWN','REASSIGNED'))
, constraint approval_notifications_status_ck  check (status in ('QUEUED','SENT','FAILED'))
, constraint approval_notifications_payload_ck check (placeholders is null or placeholders is json)
);

create index approval_notifications_queue_ix on approval_notifications (status, queued_on);

--------------------------------------------------------------------------------
-- Reference sequence for human-readable request references.
--
-- CACHE + NOORDER on purpose: ATP is a RAC database, and ORDER/NOCACHE sequences
-- serialise across instances. Gaps in a reference number are cosmetic; sequence
-- contention on the submit path is not.
--------------------------------------------------------------------------------
create sequence seq_approval_ref start with 1000 increment by 1 cache 20 noorder;
